INSERT INTO `category_1` VALUES (1,'Cam Kết','SIM trả sau mà người dùng sau khi đăng ký sử dụng, họ phải cam kết với nhà mạng sử dụng hết một mức cước phí nhất định trong 1 khoảng thời gian cụ thể'),(2,'Trả Trước','SIM điện thoại di động mà người dùng buộc phải nạp tiền vào tài khoản trước thì mới có thể sử dụng các dịch vụ như gọi điện, nhắn tin, đăng ký 3G/4G để lướt web'),(3,'Trả Sau','SIM điện thoại di động mà người dùng đăng ký với nhà mạng để có thể sử dụng trước và trả tiền sau');
