INSERT INTO `category_2` VALUES (1,'Số đẹp','Dãy số dễ nhớ, có ý nghĩa phong thủy hoặc tài lộc'),(2,'Siêu vip','SIM có giá trị cao, thường là dãy số cực kỳ đẹp và độc nhất'),(3,'Lục Quý','Dãy số có 6 chữ số giống nhau liên tiếp, cực kỳ hiếm và đắt giá'),(4,'Ngũ Quý','Dãy số có 5 chữ số giống nhau liên tiếp, rất đẹp và mang ý nghĩa may mắn'),(5,'Tứ Quý','Dãy số có 4 chữ số giống nhau liên tiếp, tượng trưng cho sự ổn định'),(6,'Tam Hoa','Dãy số có 3 chữ số giống nhau liên tiếp, dễ nhớ, tạo ấn tượng'),(7,'Số Kép','Dãy số có các cặp số giống nhau lặp lại, tạo cảm giác cân đối, dễ nhớ'),(8,'Bình Thường',NULL);
