    DECLARE emp_status INT;

    SELECT status INTO emp_status
    FROM employee
    WHERE id = NEW.employee_id;

    IF emp_status = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Không thể thêm: Nhân viên có status = 0 (đã nghỉ)';
    END IF;
END */;;
