/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_sync_account_status` AFTER UPDATE ON `employee` FOR EACH ROW BEGIN
  -- Nếu status thay đổi thành false (0)
  IF NEW.status = 0 AND OLD.status <> 0 THEN
    UPDATE account
    SET is_active = 0
    WHERE employee_id = NEW.id;

  -- Ngược lại nếu status thay đổi thành true (1)
  ELSEIF NEW.status = 1 AND OLD.status <> 1 THEN
    UPDATE account
    SET is_active = 1
    WHERE employee_id = NEW.id;
  END IF;
END */;;
DELIMITER ;
