/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_before_insert_import_receipt` BEFORE INSERT ON `import_receipt` FOR EACH ROW BEGIN
    DECLARE emp_status INT;
    DECLARE supp_status INT;

    -- Kiểm tra nếu employee_id tồn tại và lấy status
    SELECT status INTO emp_status FROM employee WHERE employee.id = NEW.employee_id;
    IF emp_status IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'employee_id không tồn tại trong bảng employee';
    END IF;

    -- Kiểm tra nếu supplier_id tồn tại và lấy status
    SELECT status INTO supp_status FROM supplier WHERE supplier.id = NEW.supplier_id;
    IF supp_status IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'supplier_id không tồn tại trong bảng supplier';
    END IF;

    -- Kiểm tra nếu status = 0
    IF emp_status = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Không thể thực hiện thao tác vì nhân viên đã nghỉ việc';
    END IF;

    IF supp_status = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Không thể thực hiện thao tác vì nhà cung cấp đã ngừng hoạt động';
    END IF;
    
    -- Kiểm tra nếu created_at >= NOW()
    IF NEW.created_at < NOW() THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'created_at phải lớn hơn hoặc bằng thời gian hiện tại';
    END IF;
END */;;
DELIMITER ;
