/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_before_update_import_receipt` BEFORE UPDATE ON `import_receipt` FOR EACH ROW BEGIN
    -- Kiểm tra nếu employee_id tồn tại trong bảng employee
    IF NOT EXISTS (SELECT 1 FROM employee WHERE employee.id = NEW.employee_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'employee_id không tồn tại trong bảng employee';
    END IF;

    -- Kiểm tra nếu supplier_id tồn tại trong bảng supplier
    IF NOT EXISTS (SELECT 1 FROM supplier WHERE supplier.id = NEW.supplier_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'supplier_id không tồn tại trong bảng supplier';
    END IF;
END */;;
DELIMITER ;
